return function(add_tbl)
    add_tbl.path = SMODS.current_mod.path
    add_tbl.loaded = {} --evil hack for compressing the regex library to be embeded so this can more easily be a single file
    function _from_base64(data)
        local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
        data = string.gsub(data, '[^' .. b .. '=]', '')
        return (data:gsub('.', function(x)
            if (x == '=') then return '' end
            local r, f = '', (b:find(x) - 1)
            for i = 6, 1, -1 do r = r .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and '1' or '0') end
            return r;
        end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)
            if (#x ~= 8) then return '' end
            local c = 0
            for i = 1, 8 do c = c + (x:sub(i, i) == '1' and 2 ^ (8 - i) or 0) end
            return string.char(c)
        end))
    end

    load_string = function(...) return loadstring(...)() end
    local string = _from_base64(
        "" ..
        "" ..
        "")
    add_tbl.REGEX = load_string(string)
    load_string = nil
    _from_base64 = nil

    function add_tbl.traverse(tbl, path)
        path = path or ""
        local paths = {}
        local vals = {}
        local order = {}
        for i, v in pairs(tbl.order or {}) do
            if type(i) == "number" then order[v] = i else order[i] = v end
        end
        for i, v in pairs(tbl) do
            local ord = i
            ord = (order)[i] or (order)[v] or ord
            vals[#vals + 1] = { v, ord, i }
        end
        table.sort(vals,
            function(a, b) return (type(a[2]) == "number" and a[2] or 0) < (type(b[2]) == "number" and b[2] or 0) end)
        for i, v in pairs(vals) do
            if type(v[1]) == "string" then
                paths[#paths + 1] = path .. "/" .. v[1]
            elseif type(v[1]) == "table" and v[2] ~= "order" then
                for i, v in pairs(add_tbl.traverse(v[1], path == "" and v[3] or path .. "/" .. (v[3]))) do
                    paths[#paths + 1] = v
                end
            end
        end
        return paths
    end

    function add_tbl.load_table(table, path)
        local paths = add_tbl.traverse(table, path)
        for i, v in pairs(paths) do
            local cont
            if not add_tbl.string_find(v, "%$") then
                local f, err = SMODS.load_file(v .. ".lua")
                if f then
                    f()
                    cont = true
                end
            end
            if not cont then
                local v2 = v:gsub("%$", "")
                if not add_tbl.load_directory(v2) then
                    error(err or v2)
                end
            end
        end
    end

    local blacklist = {
        assets = true,
        lovely = true,
        [".github"] = true,
        [".git"] = true,
        ["localization"] = true
    }

    local path_len = string.len(add_tbl.path) + 1
    function add_tbl.nfs_load_file(path)
        if not path or path == "" then
            error("No path was provided to load.")
        end
        local file_path = path
        local file_content, err = SMODS.NFS.read(file_path)
        local id = add_tbl.id or SMODS.current_mod.id
        if not file_content then
            return nil,
                "Error reading file '" .. path .. "' for mod with ID '" .. id .. "': " .. err
        end
        local short_path = string.sub(path, path_len, path:len())
        local chunk, err = load(file_content, "=[SMODS " .. id .. ' "' .. short_path .. '"]')
        if not chunk then
            return nil,
                "Error processing file '" .. path .. "' for mod with ID '" .. id .. "': " .. err
        end
        return chunk
    end

    function add_tbl.load_directory(path, regex, orders)
        local loaded = false
        if not regex then
            local p, reg = add_tbl.string_cut(path, "/")
            path = p
            regex = reg
        end
        local t = (path .. "/"):gsub("//", "/")
        add_tbl.s = add_tbl.s or {}
        add_tbl.s[path] = {}
        local info = SMODS.NFS.getDirectoryItemsInfo(add_tbl.path .. t)
        table.sort(info, function(a, b)
            return a.name < b.name
        end)
        for _, v in ipairs(info) do
            if add_tbl.string_find(v.name, regex) and v.type ~= "directory" then
                assert(add_tbl.nfs_load_file(add_tbl.path .. t .. v.name))()
                loaded = true
            elseif v.type == "directory" then
                local l = add_tbl.load_directory(t .. v.name .. "/", regex)
                loaded = loaded or l
            end
        end
        return loaded
    end

    function add_tbl.string_find(s1, s2)
        local t
        for str in string.gmatch(s1, s2) do
            t = true
        end
        return add_tbl.REGEX and add_tbl.REGEX.compile(s2):execute(s1) or t or s1 == s2
    end

    function add_tbl.string_cut(inputstr, sep)
        if sep == nil then
            sep = "%s"
        end
        local t = {}
        for str in string.gmatch(inputstr, "([^" .. sep .. "]+)") do
            table.insert(t, str)
        end
        local str = ""
        for i, v in pairs(t) do
            if i ~= #t then str = str .. v .. (i ~= #t - 1 and sep or "") end
        end
        return str, t[#t]
    end
end
